export const getGetChurchAuditViewUrl = (params?: GetChurchAuditViewParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/ministry/audit/church?${stringifiedParams}` : `/api/ministry/audit/church`
}

